import{_ as n,C as s,o as l,c as d,j as a,a as e,E as i,a3 as o}from"./chunks/framework.CZBGEXos.js";const q=JSON.parse('{"title":"Ticks","description":"","frontmatter":{},"headers":[],"relativePath":"ru/tools/ticks.md","filePath":"ru/tools/ticks.md"}'),h={name:"ru/tools/ticks.md"};function c(p,t,u,m,g,b){const r=s("Screenshot");return l(),d("div",null,[t[0]||(t[0]=a("h1",{id:"ticks",tabindex:"-1"},[e("Ticks "),a("a",{class:"header-anchor",href:"#ticks","aria-label":'Permalink to "Ticks"'},"​")],-1)),t[1]||(t[1]=a("p",null,[e("Ticks — это лента "),a("strong",null,"крупных сделок"),e(". Она показывает агрессивные покупки и продажи, превысившие заданный вами размер, в момент печати, сгруппированные по одной карточке на символ. На том же потоке она также может находить "),a("strong",null,"TWAP-цепочки"),e(" — один и тот же размер ордера, повторяющийся на одной бирже. Именно так выглядит алгоритм, который нарезает крупный ордер на части. А ещё — показывать "),a("strong",null,"ликвидации"),e(", позиции, которые биржа закрывает принудительно.")],-1)),i(r,{src:"web-ticks",alt:"Ticks в веб-версии, разделённый на панели Ticks, TWAPs и Liquidations",caption:"Ticks в веб-версии — раздельный вид с панелями Ticks, TWAPs и Liquidations"}),t[2]||(t[2]=o('<p>Если <a href="/manual/ru/tools/knives.html">Knives</a> говорит, что свеча сдвинулась, то Ticks показывает отдельные сделки, которые её сдвинули.</p><h2 id="что-такое-тик" tabindex="-1">Что такое тик <a class="header-anchor" href="#что-такое-тик" aria-label="Permalink to &quot;Что такое тик&quot;">​</a></h2><p>Тик — это один <strong>всплеск</strong> (burst): последовательные принты от одного и того же агрессора, на одной бирже и символе, объединённые в одно событие. Рыночный ордер, прошедший десять ценовых уровней, печатает десять исполнений; Ticks показывает их как один тик с суммарным размером в долларах, движением цены, которое он вызвал, и количеством принтов внутри.</p><p>Всплески формируются и фильтруются на сервере. Клиент получает только те тики, которые уже прошли ваши фильтры размера, движения, стороны и символов.</p><h3 id="биржи" tabindex="-1">Биржи <a class="header-anchor" href="#биржи" aria-label="Permalink to &quot;Биржи&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Биржа</th><th>Рынок</th></tr></thead><tbody><tr><td>Binance</td><td>Perp и spot</td></tr><tr><td>Bybit</td><td>Perp и spot</td></tr><tr><td>OKX</td><td>Perp</td></tr><tr><td>Gate.io</td><td>Perp и spot</td></tr><tr><td>Hyperliquid</td><td>Perp</td></tr><tr><td>Kraken</td><td>Spot</td></tr></tbody></table><p>Kraken используется только здесь — ни один другой инструмент его не читает.</p><h2 id="как-читать-окно" tabindex="-1">Как читать окно <a class="header-anchor" href="#как-читать-окно" aria-label="Permalink to &quot;Как читать окно&quot;">​</a></h2><h3 id="заголовок-окна" tabindex="-1">Заголовок окна <a class="header-anchor" href="#заголовок-окна" aria-label="Permalink to &quot;Заголовок окна&quot;">​</a></h3><p>Слева направо:</p><ul><li><strong>Таймфрейм</strong> — интервал свечей для графиков всех карточек. В веб-версии нажмите на него, чтобы выбрать другой; все графики переключатся сразу.</li><li><strong>Vol Ind</strong> — включает или выключает <a href="/manual/ru/customize/chart-colors.html#гистограмма-объема">гистограмму объёма</a> на всех графиках этого окна.</li><li><strong>Mixed / Split</strong> — только когда включены TWAP-цепочки или ликвидации; см. <a href="#смешанныи-и-раздельныи-вид">Смешанный и раздельный вид</a>.</li><li><strong>min $… · max $…</strong> — глобальный диапазон размера всплеска, который сейчас действует.</li><li><strong>ALL / ANY</strong> — <a href="#match-mode">режим совпадения</a>.</li><li><strong>BOTH / BUY / SELL</strong> — какая сторона агрессора учитывается.</li><li><strong>…N more</strong> — сервер упёрся в ваш <a href="#лимит-доставки">лимит доставки</a> и отбросил часть тиков. Объяснение ниже.</li><li><strong>Disconnected</strong> / <strong>Offline</strong> — состояние соединения.</li></ul><p>Пока ничего не прошло фильтры, окно показывает <code>Listening</code> и диапазон размера, на который оно настроено.</p><h3 id="карточка-символа" tabindex="-1">Карточка символа <a class="header-anchor" href="#карточка-символа" aria-label="Permalink to &quot;Карточка символа&quot;">​</a></h3><p>Для каждого символа есть <strong>одна карточка</strong>. Когда символ тикает снова — на любой бирже — новый тик становится первым в списке карточки, а сама карточка перемещается в начало. В отличие от Knives, символ, который раз за разом печатает крупные сделки, — это именно то, что нужно увидеть, так что он никогда не считается дубликатом.</p><p>В заголовке:</p><ul><li><strong>Иконка биржи</strong> — биржа, с которой рисуется график. График закрепляется за биржей, давшей <strong>первый</strong> тик символа.</li><li><strong>Символ</strong> — нажмите, чтобы скопировать.</li><li><strong>▲ / ▼</strong> — сторона последнего тика: ▲ агрессивная покупка, ▼ агрессивная продажа.</li><li><strong>$ размер</strong> — размер всплеска этого тика.</li><li><strong>% движение</strong> — насколько сместилась цена за этот всплеск.</li></ul><p>Под графиком — список тиков карточки, самые новые сверху. Каждая строка:</p><table tabindex="0"><thead><tr><th>Часть</th><th>Значение</th></tr></thead><tbody><tr><td>Время</td><td>Когда напечатался всплеск</td></tr><tr><td>Иконка биржи</td><td>Где он напечатался — может отличаться от биржи графика</td></tr><tr><td>▲ / ▼</td><td>Сторона агрессора</td></tr><tr><td>$</td><td>Размер всплеска в долларах</td></tr><tr><td>Цена</td><td>Последний принт всплеска — где остановилась лента</td></tr><tr><td>%</td><td>Движение цены за всплеск в направлении агрессора</td></tr><tr><td>×N.N</td><td>Если известно: всплеск относительно средней минуты этого символа на этой бирже (см. <a href="#minimum-volume-ratio">коэффициент объёма</a>)</td></tr><tr><td>N×</td><td>Сколько принтов объединено. Наведите, чтобы увидеть длительность и крупнейшее отдельное исполнение</td></tr></tbody></table><p>Потяните за маркер внизу любой карточки, чтобы изменить высоту списка тиков. Высота применяется ко всем карточкам.</p><p>Графики в Ticks намеренно простые: без инструментов рисования, без полноэкранного режима и без слоя мажоров. Эта лента — о том, что печатается сейчас. Единственное исключение — <a href="#отметки-на-графике">отметки ликвидаций</a>.</p><h3 id="лимит-доставки" tabindex="-1">Лимит доставки <a class="header-anchor" href="#лимит-доставки" aria-label="Permalink to &quot;Лимит доставки&quot;">​</a></h3><p>Если за секунду проходит больше тиков, чем позволяет <a href="#delivery-cap">лимит доставки</a>, сервер первыми отбрасывает <strong>самые мелкие</strong> из удерживаемых — никогда не самые новые. Тогда в заголовке появляется <code>…N more</code>.</p><p>Биржа с низким порогом размера (Kraken можно опустить до $200) даёт самые мелкие тики, так что она первой замолкает в такой ситуации. Если биржа с низким порогом постоянно пропадает, поднимите лимит.</p><h2 id="twap-цепочки" tabindex="-1">TWAP-цепочки <a class="header-anchor" href="#twap-цепочки" aria-label="Permalink to &quot;TWAP-цепочки&quot;">​</a></h2><p>TWAP-цепочка — это <strong>один и тот же размер тейкера, который повторяется</strong> на одной бирже, символе и стороне: например, 0.5 BTC покупается каждые 40 секунд. Алгоритмы исполнения именно так нарезают крупные ордера, так что цепочка может показать, что кто-то набирает или сбрасывает позицию, не напечатав ни одной крупной сделки.</p><p>TWAP-цепочки <strong>по умолчанию выключены</strong> и полностью независимы от потока тиков: можно запускать что-то одно или оба вместе.</p><div class="info custom-block"><p class="custom-block-title">Раздел TWAP появляется, только когда его поддерживает сервер</p><p>Раздел настроек скрыт, пока сервер хотя бы раз не сообщит о поддержке TWAP. Если вы его не видите, откройте окно Ticks, чтобы оно подключилось.</p></div><h3 id="карточка-twap" tabindex="-1">Карточка TWAP <a class="header-anchor" href="#карточка-twap" aria-label="Permalink to &quot;Карточка TWAP&quot;">​</a></h3><p>У карточек TWAP тот же вид «график сверху», что и у карточек тиков, — по одной на символ. В заголовке — сторона и сумма самой активной в последнее время цепочки, и <code>×N</code> — сколько цепочек сейчас у символа.</p><p>Каждая строка — одна цепочка:</p><table tabindex="0"><thead><tr><th>Часть</th><th>Значение</th></tr></thead><tbody><tr><td>▲ / ▼</td><td>Сторона</td></tr><tr><td>QTY / USD</td><td>Тип цепочки: одинаковое количество монет каждый раз или одинаковая сумма в долларах каждый раз</td></tr><tr><td><code>0.5 ≈ $32K ×14</code></td><td>Средний размер дочернего ордера, его стоимость и количество повторов на данный момент</td></tr><tr><td>$</td><td>Сколько цепочка исполнила всего</td></tr><tr><td>Интервал</td><td>Средний промежуток между повторами — настоящие алгоритмы редко бывают идеально регулярными</td></tr><tr><td>Длительность</td><td>Сколько цепочка уже идёт. Приглушенная строка <strong>завершилась</strong> — новых повторов какое-то время не было</td></tr><tr><td>%</td><td>Суммарное движение цены от первого повтора</td></tr></tbody></table><p>У некоторых строк есть метка:</p><ul><li><strong>2-SIDED</strong> — тот же размер повторяется и на противоположной стороне. Обычно это маркетмейкер или бот объёма, а не накопление.</li><li><strong>ROUND</strong> — распространённый круглый размер. Может быть много трейдеров, а не один.</li><li><strong>WEAK</strong> — на Binance, Bybit, OKX и Hyperliquid. На этих глубоких биржах одинаковые размеры часто оказываются совпадением действий многих трейдеров. Воспринимайте как подсказку.</li></ul><div class="warning custom-block"><p class="custom-block-title">Цепочка — это паттерн, а не личность</p><p>Ничто здесь не доказывает, что все повторы поставил один участник. Это лишь размер, который повторяется в ленте. Читайте его вместе с движением цены, а не вместо него.</p></div><h3 id="смешанныи-и-раздельныи-вид" tabindex="-1">Смешанный и раздельный вид <a class="header-anchor" href="#смешанныи-и-раздельныи-вид" aria-label="Permalink to &quot;Смешанный и раздельный вид&quot;">​</a></h3><p>Когда включены TWAP-цепочки или ликвидации, переключатель в заголовке меняет раскладку:</p><ul><li><strong>Mixed</strong> (по умолчанию) — карточки тиков, TWAP и ликвидаций в одной сетке, отсортированные по свежести, с меткой <code>TICK</code> / <code>TWAP</code> / <code>LIQ</code> на каждой.</li><li><strong>Split</strong> — каждый вид получает собственную панель: <strong>Ticks</strong>, <strong>TWAPs</strong> и <strong>Liquidations</strong>, каждая с количеством своих карточек. Перетащите панель за заголовок, чтобы пристыковать её к любому краю другой панели или поставить вкладкой рядом, и тяните разделитель между панелями, чтобы изменить размер. Раскладка запоминается.</li></ul><h2 id="ликвидации" tabindex="-1">Ликвидации <a class="header-anchor" href="#ликвидации" aria-label="Permalink to &quot;Ликвидации&quot;">​</a></h2><p>Ликвидация — это позиция, которую биржа закрывает принудительно, когда заканчивается маржа. Ticks показывает их с бессрочных фьючерсов <strong>Binance</strong> и <strong>Bybit</strong> — бирж, которые их публикуют, — по одной карточке на символ, как и тики.</p><p>Ликвидации <strong>включены по умолчанию</strong> и не зависят от ленты тиков и TWAP-цепочек. Когда вы открываете Ticks, сначала подгружаются ликвидации за последние 15 минут, проходящие ваши фильтры (до 50), так что панель не пустая.</p><h3 id="карточка-ликвидации" tabindex="-1">Карточка ликвидаций <a class="header-anchor" href="#карточка-ликвидации" aria-label="Permalink to &quot;Карточка ликвидаций&quot;">​</a></h3><p>В заголовке — сторона и размер последней ликвидации и <code>×N</code> — сколько их у символа на карточке. Под графиком список, новые сверху:</p><table tabindex="0"><thead><tr><th>Часть</th><th>Значение</th></tr></thead><tbody><tr><td>Время</td><td>Когда напечаталась</td></tr><tr><td>Иконка биржи</td><td>Binance или Bybit</td></tr><tr><td>▲ / ▼</td><td>Итоговое давление: ▼ принудительная продажа, ▲ принудительная покупка</td></tr><tr><td>Long / Short</td><td>Какая сторона ликвидирована</td></tr><tr><td>$</td><td>Номинал этой одной ликвидации</td></tr><tr><td>Цена</td><td>Цена закрытия</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Цвет по давлению, а не по слову</p><p>Ликвидированный <strong>лонг</strong> — это принудительная <strong>продажа</strong>; ликвидированный <strong>шорт</strong> — принудительная <strong>покупка</strong>. Строки и отметки окрашены по этому давлению, как и ромбы ликвидаций в <a href="/manual/ru/customize/majors.html">слое мажоров</a>.</p></div><h3 id="отметки-на-графике" tabindex="-1">Отметки на графике <a class="header-anchor" href="#отметки-на-графике" aria-label="Permalink to &quot;Отметки на графике&quot;">​</a></h3><p>Каждая показанная ликвидация также появляется на графике своего символа — и на карточках ликвидаций, и на карточках тиков и TWAP этого символа. Ликвидированный лонг — красная стрелка <strong>над</strong> свечой, ликвидированный шорт — зелёная стрелка <strong>под</strong> ней, с подписью размера. Несколько в одной свече складываются.</p><h2 id="настроики" tabindex="-1">Настройки <a class="header-anchor" href="#настроики" aria-label="Permalink to &quot;Настройки&quot;">​</a></h2><p>Откройте настройки Ticks: иконка справа на панели инструмента (веб) или вкладка <strong>Ticks</strong> в главном окне (Windows).</p>',48)),i(r,{src:"ticks-settings",alt:"Настройки Ticks в главном окне",caption:"Настройки Ticks"}),t[3]||(t[3]=o('<h3 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h3><h4 id="enable-ticks-feed" tabindex="-1">Enable ticks feed <a class="header-anchor" href="#enable-ticks-feed" aria-label="Permalink to &quot;Enable ticks feed&quot;">​</a></h4><p>Включает или выключает ленту крупных сделок. По умолчанию включено. На TWAP-цепочки не влияет.</p><h4 id="chart-timeframe" tabindex="-1">Chart timeframe <a class="header-anchor" href="#chart-timeframe" aria-label="Permalink to &quot;Chart timeframe&quot;">​</a></h4><p>Интервал свечей для графика каждой карточки: от <code>1m</code> до <code>1w</code>. По умолчанию <code>1m</code>.</p><h4 id="cards-kept" tabindex="-1">Cards kept <a class="header-anchor" href="#cards-kept" aria-label="Permalink to &quot;Cards kept&quot;">​</a></h4><p>Сколько карточек символов окно держит, прежде чем вытеснить самую старую. Диапазон <strong>от 3 до 50</strong>, по умолчанию 12.</p><h4 id="ticks-kept-per-card" tabindex="-1">Ticks kept per card <a class="header-anchor" href="#ticks-kept-per-card" aria-label="Permalink to &quot;Ticks kept per card&quot;">​</a></h4><p>Сколько тиков держит список каждой карточки, прежде чем отбросить самый старый. Диапазон <strong>от 10 до 500</strong> с шагом 10, по умолчанию 50.</p><h3 id="size-filters" tabindex="-1">Size filters <a class="header-anchor" href="#size-filters" aria-label="Permalink to &quot;Size filters&quot;">​</a></h3><h4 id="burst-size-range" tabindex="-1">Burst size range <a class="header-anchor" href="#burst-size-range" aria-label="Permalink to &quot;Burst size range&quot;">​</a></h4><p>Минимальный и максимальный размер всплеска в долларах. По умолчанию минимум <strong>$100 000</strong>, без максимума.</p><p>Минимум не может быть ниже серверного порога, указанного в описании ($5 000 по умолчанию). Оставьте максимум пустым, чтобы не ограничивать.</p><div class="info custom-block"><p class="custom-block-title">Максимум — это исключение, а не совпадение</p><p>Максимум действует всегда, даже в режиме <strong>Any</strong>. Он нужен, чтобы отсечь самые крупные принты — например, чтобы смотреть только на поток среднего размера.</p></div><p>Если максимум меньше минимума, диапазон ничего не пропускает, и приложение об этом предупреждает.</p><h4 id="match-mode" tabindex="-1">Match mode <a class="header-anchor" href="#match-mode" aria-label="Permalink to &quot;Match mode&quot;">​</a></h4><p>Как сочетаются три фильтра величины — минимальный размер, минимальное движение цены, минимальный коэффициент объёма. По умолчанию <strong>All</strong>.</p><ul><li><strong>All</strong> — должны пройти все заданные фильтры.</li><li><strong>Any</strong> — достаточно одного.</li></ul><h4 id="price-move-range" tabindex="-1">Price move range <a class="header-anchor" href="#price-move-range" aria-label="Permalink to &quot;Price move range&quot;">​</a></h4><p>Минимальное и максимальное движение цены за всплеск в направлении агрессора. Диапазон <strong>от 0% до 5%</strong> (серверный потолок) с шагом 0.1%. Минимум 0 = выключено, пустой максимум = без ограничения.</p><p>Движение против агрессора максимумом никогда не отсекается.</p><h4 id="minimum-volume-ratio" tabindex="-1">Minimum volume ratio <a class="header-anchor" href="#minimum-volume-ratio" aria-label="Permalink to &quot;Minimum volume ratio&quot;">​</a></h4><p>Всплеск относительно средней минуты этого символа на этой бирже за последний час. Диапазон <strong>от 0 до ×20</strong> с шагом ×0.5, по умолчанию выключено.</p><p>×5 означает, что сам всплеск проторговал в пять раз больше, чем этот символ обычно торгует на этой бирже за целую минуту. Так ловятся сделки, крупные <em>для этой монеты</em>, а не крупные в долларах.</p><h4 id="side" tabindex="-1">Side <a class="header-anchor" href="#side" aria-label="Permalink to &quot;Side&quot;">​</a></h4><p>Какую сторону агрессора учитывать: <strong>Both</strong>, <strong>Buy</strong> или <strong>Sell</strong>. По умолчанию Both.</p><h3 id="venues" tabindex="-1">Venues <a class="header-anchor" href="#venues" aria-label="Permalink to &quot;Venues&quot;">​</a></h3><p>Отдельный блок для каждой биржи. Каждую можно:</p><ul><li><strong>Выключить</strong> — с неё ничего не приходит.</li><li><strong>Дать собственный диапазон размера</strong> — заменяет глобальный размер всплеска только для этой биржи. $100K — обычное дело на перпах Binance и очень крупная сделка на тонком спотовом стакане, так что так оба остаются осмысленными.</li><li><strong>Дать собственный диапазон движения цены</strong> — то же самое для фильтра движения.</li></ul><p>Биржа без собственных значений показывает <code>global</code> и диапазон, которому она следует. У некоторых бирж серверный порог ниже, чем у остальных, — блок об этом сообщает. Их тики самые мелкие в потоке, так что именно их первыми отбрасывает <a href="#delivery-cap">лимит доставки</a>.</p><p>Если выключены все биржи, приложение предупреждает, что ничего не придёт.</p><h3 id="twap-chains" tabindex="-1">TWAP Chains <a class="header-anchor" href="#twap-chains" aria-label="Permalink to &quot;TWAP Chains&quot;">​</a></h3><h4 id="twap-chains-1" tabindex="-1">TWAP Chains <a class="header-anchor" href="#twap-chains-1" aria-label="Permalink to &quot;TWAP Chains&quot;">​</a></h4><p>Включает или выключает поиск TWAP-цепочек. <strong>По умолчанию выключено.</strong></p><h4 id="cards-kept-1" tabindex="-1">Cards kept <a class="header-anchor" href="#cards-kept-1" aria-label="Permalink to &quot;Cards kept&quot;">​</a></h4><p>Лимит карточек TWAP. Отдельный от лимита карточек тиков. Диапазон <strong>от 3 до 50</strong>, по умолчанию 12.</p><h4 id="min-child-size" tabindex="-1">Min child size <a class="header-anchor" href="#min-child-size" aria-label="Permalink to &quot;Min child size&quot;">​</a></h4><p>Минимальный средний размер одного повтора в долларах. По умолчанию <strong>$1 000</strong>. Серверного порога нет: бывают настоящие цепочки с повторами по $20.</p><h4 id="min-repeats" tabindex="-1">Min repeats <a class="header-anchor" href="#min-repeats" aria-label="Permalink to &quot;Min repeats&quot;">​</a></h4><p>Минимальное количество повторов на данный момент. Диапазон <strong>от 3 до 50</strong>, по умолчанию 5. Всё, что меньше 3, сервер считает за 3.</p><h4 id="min-total-size" tabindex="-1">Min total size <a class="header-anchor" href="#min-total-size" aria-label="Permalink to &quot;Min total size&quot;">​</a></h4><p>Минимальная сумма, которую цепочка уже исполнила. Пусто = выключено.</p><h4 id="min-price-move" tabindex="-1">Min price move <a class="header-anchor" href="#min-price-move" aria-label="Permalink to &quot;Min price move&quot;">​</a></h4><p>Минимальное суммарное движение цены на данный момент в направлении агрессора. Диапазон <strong>от 0% до 5%</strong>. Большинство цепочек почти не двигают цену, так что высокое значение не покажет почти ничего.</p><h4 id="chain-kind" tabindex="-1">Chain kind <a class="header-anchor" href="#chain-kind" aria-label="Permalink to &quot;Chain kind&quot;">​</a></h4><ul><li><strong>Qty</strong> — одинаковое количество монет каждый раз.</li><li><strong>Usd</strong> — одинаковая сумма в долларах каждый раз.</li><li><strong>Both</strong> (по умолчанию).</li></ul><h4 id="max-average-gap" tabindex="-1">Max average gap <a class="header-anchor" href="#max-average-gap" aria-label="Permalink to &quot;Max average gap&quot;">​</a></h4><p>Только цепочки, повторы которых в среднем отстоят друг от друга не больше чем на столько секунд. Пусто = выключено.</p><h4 id="hide-two-sided" tabindex="-1">Hide two-sided <a class="header-anchor" href="#hide-two-sided" aria-label="Permalink to &quot;Hide two-sided&quot;">​</a></h4><p>Убирает цепочки, где тот же размер повторяется и на противоположной стороне, — помеченные <strong>2-SIDED</strong>. По умолчанию выключено.</p><h3 id="twap-venues" tabindex="-1">TWAP Venues <a class="header-anchor" href="#twap-venues" aria-label="Permalink to &quot;TWAP Venues&quot;">​</a></h3><p>Поиск TWAP работает на Kraken spot, Gate.io perp и spot, Hyperliquid, Binance, Bybit и OKX. Каждую биржу можно выключить и задать ей собственные <strong>Min child $</strong> и <strong>Min repeats</strong>.</p><p>На Binance, Bybit и OKX серверный минимум дочернего ордера — <strong>$5 000</strong>. Меньшие повторы там вообще не отслеживаются, так что более низкая настройка на этих биржах ничего не найдёт — блок сообщает, когда это так.</p><h3 id="symbol-whitelist" tabindex="-1">Symbol whitelist <a class="header-anchor" href="#symbol-whitelist" aria-label="Permalink to &quot;Symbol whitelist&quot;">​</a></h3><p>Эти фильтры действуют <strong>и на тики, и на TWAP-цепочки</strong>.</p><h4 id="symbol-whitelist-1" tabindex="-1">Symbol whitelist <a class="header-anchor" href="#symbol-whitelist-1" aria-label="Permalink to &quot;Symbol whitelist&quot;">​</a></h4><p>Показывать только эти символы. Пустой список показывает все. Введите символ и нажмите <kbd>Enter</kbd>; несколько можно добавить сразу через запятую.</p><h4 id="blacklist" tabindex="-1">Blacklist <a class="header-anchor" href="#blacklist" aria-label="Permalink to &quot;Blacklist&quot;">​</a></h4><p>Символы, которые никогда не показывать. По умолчанию: <code>BTCUSDT</code>, <code>ETHUSDT</code>, <code>BTCUSD</code>, <code>ETHUSD</code> — две главные монеты печатают крупные сделки непрерывно и иначе заполнили бы всё окно.</p><div class="warning custom-block"><p class="custom-block-title">Каждая биржа пишет символ по-своему</p><p>Символы сравниваются так, как их пишет биржа. Kraken присылает <code>BTCUSD</code>, а не <code>BTCUSDT</code>. Чтобы заблокировать или отслеживать монету везде, добавьте все её написания.</p></div><h4 id="exclude-stock-commodity-perps" tabindex="-1">Exclude stock/commodity perps <a class="header-anchor" href="#exclude-stock-commodity-perps" aria-label="Permalink to &quot;Exclude stock/commodity perps&quot;">​</a></h4><p>Убирает XAU, XAG, TSLA и подобные токенизированные перпы. По умолчанию выключено.</p><h4 id="minimum-24h-turnover" tabindex="-1">Minimum 24h turnover <a class="header-anchor" href="#minimum-24h-turnover" aria-label="Permalink to &quot;Minimum 24h turnover&quot;">​</a></h4><p>Скрывает тонкие символы по 24-часовому обороту. Диапазон <strong>от $0 до $50M</strong> с шагом $1M, по умолчанию выключено. Ненулевое значение также скрывает символы, оборот которых ещё неизвестен.</p><h4 id="delivery-cap" tabindex="-1">Delivery cap <a class="header-anchor" href="#delivery-cap" aria-label="Permalink to &quot;Delivery cap&quot;">​</a></h4><p>Максимальное количество тиков в секунду, которое сервер доставляет, прежде чем начать отбрасывать самые мелкие из удерживаемых. Диапазон <strong>от 1 до 200</strong>, по умолчанию 20.</p><h3 id="liquidations" tabindex="-1">Liquidations <a class="header-anchor" href="#liquidations" aria-label="Permalink to &quot;Liquidations&quot;">​</a></h3><h4 id="enable-liquidation-tape" tabindex="-1">Enable liquidation tape <a class="header-anchor" href="#enable-liquidation-tape" aria-label="Permalink to &quot;Enable liquidation tape&quot;">​</a></h4><p>Показывает принудительные закрытия позиций в момент, когда они происходят. <strong>Включено по умолчанию.</strong> Пока выключено, всё ниже неактивно.</p><h4 id="cards-kept-2" tabindex="-1">Cards kept <a class="header-anchor" href="#cards-kept-2" aria-label="Permalink to &quot;Cards kept&quot;">​</a></h4><p>Сколько карточек ликвидаций держит окно, прежде чем убрать самые старые. Диапазон <strong>от 3 до 50</strong>, по умолчанию 12.</p><h4 id="minimum-size" tabindex="-1">Minimum size <a class="header-anchor" href="#minimum-size" aria-label="Permalink to &quot;Minimum size&quot;">​</a></h4><p>Размер одной ликвидации в USD. Диапазон <strong>от $5 000 до $1 000 000</strong> с шагом $5 000, по умолчанию $50 000. Действует для каждой биржи без собственного размера. $5 000 — собственный минимум сервера.</p><p>Ничего не суммируется: ликвидация показывается, если она сама не меньше этого размера.</p><h4 id="настроики-для-каждои-биржи" tabindex="-1">Настройки для каждой биржи <a class="header-anchor" href="#настроики-для-каждои-биржи" aria-label="Permalink to &quot;Настройки для каждой биржи&quot;">​</a></h4><p>По одному блоку для <strong>Binance</strong> и <strong>Bybit</strong>:</p><ul><li>Переключатель, чтобы полностью выключить биржу.</li><li><strong>Size on this venue</strong> — собственный минимальный размер. Выключен — действует минимальный размер выше.</li></ul><p>$50K — обыденность на Binance, но может быть крупным событием в другом месте, поэтому собственный размер для каждой биржи не даёт одной заглушить другую. Если обе биржи выключены, приложение предупредит, что ничего не придёт.</p><h4 id="minimum-24h-turnover-1" tabindex="-1">Minimum 24h turnover <a class="header-anchor" href="#minimum-24h-turnover-1" aria-label="Permalink to &quot;Minimum 24h turnover&quot;">​</a></h4><p>Скрывает малоликвидные символы по обороту за 24 часа. Диапазон <strong>от $0 до $50M</strong> с шагом $1M, по умолчанию выключено. Ненулевое значение также скрывает символы, чей оборот ещё неизвестен.</p><h4 id="blacklist-1" tabindex="-1">Blacklist <a class="header-anchor" href="#blacklist-1" aria-label="Permalink to &quot;Blacklist&quot;">​</a></h4><p>Символы, которые никогда не показывать. Введите символ и нажмите <kbd>Enter</kbd>; <strong>Clear all</strong> очищает список.</p><h4 id="liquidation-sound" tabindex="-1">Liquidation sound <a class="header-anchor" href="#liquidation-sound" aria-label="Permalink to &quot;Liquidation sound&quot;">​</a></h4><p>Воспроизводит звук, когда приходит ликвидация. <strong>Выключено по умолчанию.</strong> Срабатывает на каждую ликвидацию, прошедшую фильтры, — сначала поднимите <strong>Minimum size</strong>, потом включайте.</p><h3 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h3><h4 id="tick-sound" tabindex="-1">Tick sound <a class="header-anchor" href="#tick-sound" aria-label="Permalink to &quot;Tick sound&quot;">​</a></h4><p>Воспроизводит звук, когда приходит тик, прошедший фильтры. <strong>По умолчанию выключено.</strong> С низким минимальным размером это будет срабатывать очень часто — сначала настройте фильтры.</p><h2 id="связанное" tabindex="-1">Связанное <a class="header-anchor" href="#связанное" aria-label="Permalink to &quot;Связанное&quot;">​</a></h2><ul><li><a href="/manual/ru/customize/majors.html">Слой мажоров</a> — крупные сделки на графике по цене, где они напечатались</li><li><a href="/manual/ru/tools/knives.html">Knives</a> — движение на уровне свечи, а не отдельные сделки</li></ul>',89))])}const P=n(h,[["render",c]]);export{q as __pageData,P as default};
